const input = $input.all()[0].json;
if (!input.companies || !Array.isArray(input.companies) || input.companies.length === 0) {
  throw new Error('Input muss "companies" Array enthalten');
}
for (const company of input.companies) {
  if (!company.name) throw new Error('Jede Company braucht einen "name"');
  if (!company.target_titles || company.target_titles.length === 0) {
    throw new Error(`Company "${company.name}" braucht "target_titles"`);
  }
}
const campaign = input.campaign || {};
campaign.name = campaign.name || `Outreach ${new Date().toISOString().slice(0,10)}`;
campaign.language = campaign.language || 'de';
campaign.max_emails_per_day = campaign.max_emails_per_day || 30;
campaign.follow_up_days = campaign.follow_up_days || [3, 7, 14];
campaign.email_template_id = campaign.email_template_id || 'oracle_isv_default';

return input.companies.map(c => ({
  json: { company: c, campaign }
}));

const html = $input.all()[0].json.data || $input.all()[0].json.body || '';
const companyData = $input.all()[0].json.company || $('Split Companies').first().json.company;
const campaign = $input.all()[0].json.campaign || $('Split Companies').first().json.campaign;

const metaMatch = html.match(/<meta[^>]*name=["']description["'][^>]*content=["']([^"']+)["']/i);
const description = metaMatch ? metaMatch[1] : String(html).replace(/<[^>]+>/g, ' ').substring(0, 500).trim();

const techKeywords = ['oracle', 'aws', 'azure', 'cloud', 'saas', 'api', 'database', 'kubernetes', 'docker', 'java', '.net', 'python', 'microservices', 'iot', 'ai', 'machine learning'];
const htmlLower = String(html).toLowerCase();
const foundTech = techKeywords.filter(kw => htmlLower.includes(kw));

const industryKeywords = ['manufacturing', 'finance', 'insurance', 'healthcare', 'logistics', 'retail', 'energy', 'automotive', 'pharma', 'medtech', 'security', 'banking'];
const foundIndustry = industryKeywords.filter(kw => htmlLower.includes(kw));

return [{
  json: {
    company: { ...companyData, description, tech_stack_indicators: foundTech, industry_indicators: foundIndustry, analyzed_at: new Date().toISOString() },
    campaign
  }
}];

const company = $input.all()[0].json.company;
const campaign = $input.all()[0].json.campaign;

return company.target_titles.map(title => ({
  json: {
    search_query: `${title} ${company.name}`,
    company_name: company.name,
    target_title: title,
    company_data: company,
    campaign
  }
}));

const results = $input.all()[0].json;
const companyData = $('Build Phantombuster Searches').first().json.company_data;
const targetTitle = $('Build Phantombuster Searches').first().json.target_title;
const campaign = $('Build Phantombuster Searches').first().json.campaign;

let profiles = [];
try {
  const outputRaw = results.output || results.data || '[]';
  const output = typeof outputRaw === 'string' ? JSON.parse(outputRaw) : outputRaw;
  const arr = Array.isArray(output) ? output : [];
  profiles = arr
    .filter(p => p.name && p.profileUrl)
    .map(p => ({
      full_name: p.name,
      first_name: p.name.split(' ')[0],
      last_name: p.name.split(' ').slice(1).join(' '),
      linkedin_url: p.profileUrl,
      job_title: p.title || targetTitle,
      company_mentioned: p.companyName || companyData.name,
      location: p.location || '',
      headline: p.headline || ''
    }));
} catch (e) {
  profiles = [];
}

if (profiles.length === 0) return [];

return profiles.map(p => ({
  json: { profile: p, company_data: companyData, campaign }
}));

const items = $input.all();
const seen = new Set();
const unique = [];
for (const item of items) {
  const url = item.json.profile.linkedin_url;
  if (!seen.has(url)) {
    seen.add(url);
    unique.push(item);
  }
}
return unique.slice(0, 5);

const prospeoResult = $input.all()[0].json;
const profileNode = $('Deduplicate Profiles');
const profile = profileNode.first().json.profile;
const companyData = profileNode.first().json.company_data;
const campaign = profileNode.first().json.campaign;

let email = null;
let emailConfidence = 0;

if (prospeoResult.response && prospeoResult.response.email) {
  email = prospeoResult.response.email;
  emailConfidence = prospeoResult.response.email_confidence || prospeoResult.response.confidence || 0;
}

if (!email) return [];

return [{
  json: {
    profile: { ...profile, email, email_confidence: emailConfidence, email_source: 'prospeo' },
    company_data: companyData,
    campaign
  }
}];

const bouncerResult = $input.all()[0].json;
const prevData = $('Wait — Rate Limit Prospeo').first().json;
const profile = prevData.profile;
const companyData = prevData.company_data;
const campaign = prevData.campaign;

const status = bouncerResult.status || 'unknown';
const isValid = ['deliverable', 'risky'].includes(status);

if (!isValid) return [];

return [{
  json: {
    profile: { ...profile, email_verified: true, email_status: status, email_reason: bouncerResult.reason || '' },
    company_data: companyData,
    campaign
  }
}];

const profile = $input.all()[0].json.profile;
const company = $input.all()[0].json.company_data;
const campaign = $input.all()[0].json.campaign;

let score = 0;
const details = {};

// 1. METRICS (0-20): Tech-Stack Indikatoren = Cloud/DB-Bedarf
const techScore = Math.min((company.tech_stack_indicators?.length || 0) * 4, 20);
score += techScore;
details.metrics = { score: techScore, reason: `${company.tech_stack_indicators?.length || 0} Tech-Indikatoren` };

// 2. ECONOMIC BUYER (0-20): Entscheider-Position?
const buyerTitles = ['ceo', 'cto', 'cfo', 'cio', 'vp', 'vice president', 'director', 'head of', 'geschäftsführer', 'vorstand', 'leiter'];
const titleLower = (profile.job_title || '').toLowerCase();
const isBuyer = buyerTitles.some(t => titleLower.includes(t));
const buyerScore = isBuyer ? 20 : (titleLower.includes('manager') ? 10 : 5);
score += buyerScore;
details.economic_buyer = { score: buyerScore, reason: profile.job_title };

// 3. DECISION CRITERIA (0-15): Tech-Relevanz des Titels
const techTitles = ['cloud', 'infrastructure', 'platform', 'data', 'digital', 'transformation', 'it ', 'technology', 'engineering', 'development', 'software'];
const techRelevance = techTitles.filter(t => titleLower.includes(t)).length;
const dcScore = Math.min(techRelevance * 5, 15);
score += dcScore;
details.decision_criteria = { score: dcScore, reason: `${techRelevance} tech-Keywords im Titel` };

// 4. DECISION PROCESS (0-15): Email Confidence als Erreichbarkeits-Proxy
const emailConfScore = profile.email_confidence > 90 ? 15 : (profile.email_confidence > 70 ? 10 : 5);
score += emailConfScore;
details.decision_process = { score: emailConfScore, reason: `Email Confidence: ${profile.email_confidence}%` };

// 5. IDENTIFY PAIN (0-15): Industrie-Relevanz für Oracle
const oracleIndustries = ['finance', 'insurance', 'banking', 'manufacturing', 'logistics', 'healthcare', 'energy', 'retail', 'automotive'];
const industryMatch = (company.industry_indicators || []).filter(i => oracleIndustries.includes(i)).length;
const painScore = Math.min(industryMatch * 5, 15);
score += painScore;
details.identify_pain = { score: painScore, reason: `${industryMatch} Oracle-relevante Branchen` };

// 6. CHAMPION (0-15): LinkedIn Headline als Aktivitäts-Proxy
const championScore = profile.headline?.length > 50 ? 15 : (profile.headline?.length > 20 ? 10 : 5);
score += championScore;
details.champion = { score: championScore, reason: `Headline ${profile.headline?.length || 0} Zeichen` };

// Kategorisierung
let category;
if (score >= 70) category = 'HOT';
else if (score >= 45) category = 'WARM';
else category = 'COLD';

return [{
  json: {
    lead: { ...profile, meddic_score: score, meddic_category: category, meddic_details: details },
    company_data: company,
    campaign
  }
}];

const lead = $input.all()[0].json.lead;
const company = $input.all()[0].json.company_data;
const campaign = $input.all()[0].json.campaign;

const templates = {
  oracle_isv_default: {
    subject_de: 'Cloud-Infrastruktur für {companyName}?',
    body_de: 'Sehr geehrte/r {firstName} {lastName},\n\nich kontaktiere Sie, da {companyName} als innovatives Unternehmen in {industry} sicherlich von einer skalierbaren Cloud-Infrastruktur profitieren könnte.\n\nOracle Cloud Infrastructure (OCI) bietet ISV-Partnern wie {companyName} besondere Vorteile:\n\n- Bis zu 50% Kostenersparnis gegenüber anderen Hyperscalern\n- Universal Credits für flexible Nutzung aller Cloud-Services\n- Dedizierte EU Sovereign Cloud für DSGVO-Compliance\n- Multicloud-Integration mit Azure und AWS\n\nHätten Sie nächste Woche 15 Minuten für ein kurzes Gespräch?\n\nMit freundlichen Grüßen'
  },
  oracle_isv_multicloud: {
    subject_de: 'Multicloud-Strategie für {companyName}',
    body_de: 'Sehr geehrte/r {firstName} {lastName},\n\ndie Multicloud-Strategie gewinnt für ISVs in {industry} zunehmend an Bedeutung. Oracle hat mit Database@Azure und der OCI-AWS Interconnect eine neue Ära der Multicloud-Integration eingeläutet.\n\nFür {companyName} könnte dies bedeuten:\n- Ihre bestehende Infrastruktur bleibt — Oracle ergänzt nahtlos\n- Oracle Database Services direkt in Azure verfügbar\n- Universal Credits: Ein Budget, alle Services\n\nDarf ich Ihnen in einem 15-minütigen Call zeigen, wie andere ISVs in der DACH-Region davon profitieren?\n\nMit freundlichen Grüßen'
  }
};

const template = templates[campaign.email_template_id] || templates.oracle_isv_default;
const lang = campaign.language || 'de';

let subject = template[`subject_${lang}`] || template.subject_de;
let body = template[`body_${lang}`] || template.body_de;

const replacements = {
  '{firstName}': lead.first_name,
  '{lastName}': lead.last_name,
  '{companyName}': company.name,
  '{industry}': (company.industry_indicators || ['Technology']).join(', ')
};

for (const [key, value] of Object.entries(replacements)) {
  subject = subject.split(key).join(value);
  body = body.split(key).join(value);
}

return [{
  json: {
    email_to: lead.email,
    email_subject: subject,
    email_body: body,
    lead,
    company_data: company,
    campaign,
    sequence_step: 1,
    sent_at: null
  }
}];

const staticData = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);

if (!staticData.emailsSent) staticData.emailsSent = {};
if (!staticData.emailsSent[today]) staticData.emailsSent[today] = 0;

const limit = $input.all()[0].json.campaign.max_emails_per_day || 30;
const sentToday = staticData.emailsSent[today];

if (sentToday >= limit) {
  return [{
    json: { ...($input.all()[0].json), delayed: true, delay_reason: `Tageslimit ${limit} erreicht (${sentToday} gesendet)` }
  }];
}

staticData.emailsSent[today] = sentToday + 1;
return [{
  json: { ...($input.all()[0].json), delayed: false, email_number_today: sentToday + 1 }
}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.sentEmails) staticData.sentEmails = [];

const prevData = $('Check Daily Email Limit').first().json;

const record = {
  email: prevData.email_to,
  lead_name: prevData.lead.full_name,
  company: prevData.company_data.name,
  subject: prevData.email_subject,
  sent_at: new Date().toISOString(),
  sequence_step: prevData.sequence_step,
  follow_up_days: prevData.campaign.follow_up_days,
  next_follow_up: null
};

const followUpDays = record.follow_up_days || [3, 7, 14];
if (record.sequence_step <= followUpDays.length) {
  const daysUntil = followUpDays[record.sequence_step - 1];
  record.next_follow_up = new Date(Date.now() + daysUntil * 86400000).toISOString();
}

staticData.sentEmails.push(record);

return [{
  json: { ...(prevData), sent_at: record.sent_at, next_follow_up: record.next_follow_up }
}];

const staticData = $getWorkflowStaticData('global');
const leads = staticData.allLeads || [];

const headers = [
  'Firma', 'Website', 'Branche', 'Tech-Stack',
  'Name', 'Jobtitel', 'Email', 'Email Verifiziert', 'Email Status', 'Email Confidence',
  'LinkedIn', 'Standort', 'Headline',
  'MEDDIC Score', 'MEDDIC Kategorie',
  'Metrics', 'Metrics Detail',
  'Economic Buyer', 'EB Detail',
  'Decision Criteria', 'DC Detail',
  'Decision Process', 'DP Detail',
  'Identify Pain', 'IP Detail',
  'Champion', 'Champion Detail',
  'Kampagne', 'Zeitstempel'
];

const rows = leads.map(l => [
  l.company, l.website, l.industry, l.tech_stack,
  l.full_name, l.job_title, l.email, l.email_verified, l.email_status, l.email_confidence,
  l.linkedin_url, l.location, l.headline,
  l.meddic_score, l.meddic_category,
  l.metrics_score, l.metrics_reason,
  l.economic_buyer_score, l.economic_buyer_reason,
  l.decision_criteria_score, l.decision_criteria_reason,
  l.decision_process_score, l.decision_process_reason,
  l.identify_pain_score, l.identify_pain_reason,
  l.champion_score, l.champion_reason,
  l.campaign, l.timestamp
]);

const csvContent = [headers, ...rows]
  .map(row => row.map(cell => `"${String(cell || '').replace(/"/g, '""')}"`).join(','))
  .join('\n');

const buffer = Buffer.from(csvContent, 'utf-8');
const fileName = `MEDDIC_Leads_${new Date().toISOString().slice(0,10)}.csv`;

staticData.excelFileName = fileName;

return [{
  json: {
    fileName,
    totalLeads: leads.length,
    hotLeads: leads.filter(l => l.meddic_category === 'HOT').length,
    warmLeads: leads.filter(l => l.meddic_category === 'WARM').length,
    coldLeads: leads.filter(l => l.meddic_category === 'COLD').length
  },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'text/csv',
      fileName
    }
  }
}];

const staticData = $getWorkflowStaticData('global');
const allLeads = staticData.allLeads || [];
const sentEmails = staticData.sentEmails || [];

const summary = {
  timestamp: new Date().toISOString(),
  total_leads_found: allLeads.length,
  leads_by_category: {
    HOT: allLeads.filter(l => l.meddic_category === 'HOT').length,
    WARM: allLeads.filter(l => l.meddic_category === 'WARM').length,
    COLD: allLeads.filter(l => l.meddic_category === 'COLD').length
  },
  emails_sent: sentEmails.length,
  excel_file: staticData.excelFileName || 'MEDDIC_Leads.csv',
  companies_processed: [...new Set(allLeads.map(l => l.company))].length
};

return [{ json: summary }];
